package com.bank.ledger;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;
import java.util.logging.*;

public class FairLockDemo {
    private static final Logger LOG = Logger.getLogger("Ledger");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        runScenario(false);   // unfair: audit likely starved
        runScenario(true);    // fair: audit served in FIFO order
    }

    static void runScenario(boolean fair) throws Exception {
        LOG.info(() -> "=== mode: " + (fair ? "FAIR" : "UNFAIR") + " ===");
        Account account = new Account("SAV2001", new BigDecimal("1000000"), fair);
        AtomicInteger auditServed = new AtomicInteger();
        ExecutorService pool = Executors.newFixedThreadPool(9);

        for (int i = 0; i < 8; i++)                         // 8 fast transaction threads
            pool.submit(new TransactionWorker(account, new BigDecimal("1")));
        pool.submit(new AuditWorker(account, auditServed));  // 1 slow audit thread

        Thread.sleep(500);
        pool.shutdownNow();
        pool.awaitTermination(2, TimeUnit.SECONDS);
        LOG.info(() -> "audit served " + auditServed.get() + " times (" + (fair ? "FAIR" : "UNFAIR") + ")");
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String id;
    private BigDecimal balance;
    private final ReentrantLock lock;
    Account(String id, BigDecimal balance, boolean fair) {
        this.id = id; this.balance = balance;
        this.lock = new ReentrantLock(fair);   // fair=true → FIFO, no starvation
    }
    void debit(BigDecimal amt) {
        lock.lock();
        try { balance = balance.subtract(amt); } finally { lock.unlock(); }
    }
    boolean auditPass() {
        lock.lock();
        try { return balance.signum() >= 0; } finally { lock.unlock(); }
    }
}

// ─── Would be in worker/TransactionWorker.java ───
class TransactionWorker implements Runnable {
    private final Account account;
    private final BigDecimal amount;
    TransactionWorker(Account account, BigDecimal amount) { this.account = account; this.amount = amount; }
    @Override public void run() {
        while (!Thread.currentThread().isInterrupted()) {
            account.debit(amount);   // hammer the lock repeatedly (high frequency)
        }
    }
}

// ─── Would be in worker/AuditWorker.java ───
class AuditWorker implements Runnable {
    private final Account account;
    private final AtomicInteger served;
    AuditWorker(Account account, AtomicInteger served) { this.account = account; this.served = served; }
    @Override public void run() {
        while (!Thread.currentThread().isInterrupted()) {
            if (account.auditPass()) served.incrementAndGet();  // needs the same lock
        }
    }
}
